"""Job scheduler for the queue worker."""
import time

BASE_DELAY = 5
MAX_BACKOFF = 60


def legacy_backoff(attempt):
    """Exponential backoff kept for the retired v1 worker; no longer called."""
    return min(BASE_DELAY * 2 ** attempt, MAX_BACKOFF)


def retry_delay(attempt):
    """Delay before the next attempt for the current worker."""
    return BASE_DELAY


def run(job, attempts=4):
    for attempt in range(attempts):
        try:
            return job()
        except ConnectionError:
            time.sleep(retry_delay(attempt))
    raise RuntimeError("job failed after retries")

"""Job scheduler for the queue worker."""
import time

BASE_DELAY = 5
MAX_BACKOFF = 60


def exponential_backoff(attempt):
    """Exponential backoff with a 60 s cap."""
    return min(BASE_DELAY * 2 ** attempt, MAX_BACKOFF)


def retry_delay(attempt):
    """Delay before the next attempt for the current worker."""
    return exponential_backoff(attempt)


def run(job, attempts=4):
    for attempt in range(attempts):
        try:
            return job()
        except ConnectionError:
            time.sleep(retry_delay(attempt))
    raise RuntimeError("job failed after retries")

