import os

DEFAULTS = {
    "CONTEXT_FILTER": "auto",      # auto | ranker | keyword | embeddings | none
    "SIMILARITY_THRESHOLD": 0.42,
    "SMALL_INPUT_CHARS": 8000,
}


class Config:
    def __init__(self, **overrides):
        values = {**DEFAULTS, **overrides}
        self.context_filter = values["CONTEXT_FILTER"]
        self.similarity_threshold = values["SIMILARITY_THRESHOLD"]
        self.small_input_chars = values["SMALL_INPUT_CHARS"]


def resolve_filter(setting):
    """auto means the hosted ranker when its key is set, otherwise keyword ranking."""
    if setting == "auto":
        return "ranker" if os.environ.get("PAGEBRIEF_RANKER_KEY") else "keyword"
    return setting

