from ..config import resolve_filter
from .embedding import EmbeddingFilter
from .keyword import KeywordFilter
from .ranker import HostedRanker


def select(query, pages, config):
    mode = resolve_filter(config.context_filter)
    if mode == "none":
        return "\n\n".join(page["text"] for page in pages)
    if sum(len(page["text"]) for page in pages) < config.small_input_chars:
        return "\n\n".join(page["text"] for page in pages)
    if mode == "ranker":
        return HostedRanker().top(query, pages)
    if mode == "embeddings":
        return EmbeddingFilter(threshold=config.similarity_threshold).top(query, pages)
    return KeywordFilter(relative_threshold=0.5, max_chunks=25).top(query, pages)

