import urllib.request

CHUNK_CHARS = 1000


class PageFetcher:
    """Download pages, extract text and split it into verbatim chunks."""

    def snippets(self, urls):
        result = {}
        for url in urls:
            with urllib.request.urlopen(url, timeout=4) as response:
                text = response.read().decode("utf-8", "replace")
            result[url] = [text[i:i + CHUNK_CHARS] for i in range(0, len(text), CHUNK_CHARS)]
        return result

