from ..fetch import PageFetcher


class BingRetriever:
    def __init__(self, client):
        self.client = client
        self.fetcher = PageFetcher()

    def search(self, query):
        urls = [hit["url"] for hit in self.client.web(query)]
        pages = self.fetcher.snippets(urls)
        return [{"url": url, "snippets": chunks} for url, chunks in pages.items()]

