from ..fetch import PageFetcher


class SerperRetriever:
    def __init__(self, client, extra_extraction=False):
        self.client = client
        self.extra_extraction = extra_extraction
        self.fetcher = PageFetcher()

    def search(self, query):
        hits = self.client.organic(query)
        pages = self.fetcher.snippets([h["link"] for h in hits]) if self.extra_extraction else {}
        return [{"url": h["link"], "snippets": [h["snippet"], *pages.get(h["link"], [])]} for h in hits]

